```ts
import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachConfigurableFreeControl } from "@babylonjs/lite";

const BIG_WORLD_MULTIPLIER = 20;

// KeyboardEvent.code values for the default free-camera movement keys:
// WASD, arrows, and the keys that rise/sink.
const BIG_WORLD_MOVEMENT_KEYS = [
  "KeyW",
  "KeyA",
  "KeyS",
  "KeyD",
  "ArrowUp",
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
  "Space",
  "PageUp",
  "ShiftLeft",
  "ShiftRight",
  "PageDown",
];

export function attachBigWorldFly(
  camera: FreeCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
): () => void {
  const hadTabIndex = canvas.hasAttribute("tabindex");
  const originalTabIndex = hadTabIndex ? canvas.getAttribute("tabindex") : null;

  const dispose = attachConfigurableFreeControl(camera, canvas, scene, {
    fastKeys: [...BIG_WORLD_MOVEMENT_KEYS],
    fastMultiplier: BIG_WORLD_MULTIPLIER,
  });

  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;

    dispose();

    if (hadTabIndex && originalTabIndex !== null) {
      canvas.setAttribute("tabindex", originalTabIndex);
    } else {
      canvas.removeAttribute("tabindex");
    }
  };
}
```

I added `src/big-world-fly.ts` using the library’s configurable free-camera controls, passing the default movement key codes as `fastKeys` and `fastMultiplier: 20` while leaving mouse look untouched; the returned cleanup disposes the controls and restores the canvas `tabindex` if it was changed. I’m not fully sure whether `fastKeys` is intended to accept the movement keys themselves rather than separate modifier keys, and whether the library’s own dispose already restores `tabindex`; I assumed it does not and restore it defensively.
